package ru.meguboom.mobile;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** One document per device avoids concurrent writers overwriting another device's work. */
final class ProgressSync {
 interface Transport{String request(String method,String url,String body,String contentType)throws Exception;}
 static final String API="https://www.googleapis.com/drive/v3/files",UPLOAD="https://www.googleapis.com/upload/drive/v3/files",PREFIX="meguboom-progress-v1-";
 static class Result{JSONObject own,merged;int rejected;Result(JSONObject a,JSONObject b,int n){own=a;merged=b;rejected=n;}}
 static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static boolean same(JSONObject a,JSONObject b){if(a.length()!=b.length())return false;for(Iterator<String> it=a.keys();it.hasNext();){String id=it.next();JSONObject x=a.optJSONObject(id),y=b.optJSONObject(id);if(x==null||y==null||x.optLong("positionMs")!=y.optLong("positionMs")||x.optLong("durationMs")!=y.optLong("durationMs")||x.optLong("updatedAt")!=y.optLong("updatedAt")||x.optBoolean("completed")!=y.optBoolean("completed")||!x.optString("deviceId").equals(y.optString("deviceId")))return false;}return true;}
 static Result exchange(String device,JSONObject local,Transport api)throws Exception{JSONObject own=new JSONObject(local.toString()),merged=new JSONObject(),remoteOwn=new JSONObject();String name=PREFIX+device+".json",ownId="",page="";Set<String> pages=new HashSet<>();int rejected=0,count=0;do{JSONObject listing=new JSONObject(api.request("GET",API+"?spaces=appDataFolder&pageSize=1000&q="+enc("trashed = false and name contains '"+PREFIX+"'")+"&fields="+enc("files(id,name),nextPageToken")+(page.isEmpty()?"":"&pageToken="+enc(page)),"",""));JSONArray files=listing.optJSONArray("files");if(files!=null)for(int i=0;i<files.length();i++){if(++count>2000)throw new IOException("Слишком много файлов синхронизации");JSONObject f=files.getJSONObject(i);String id=f.optString("id");if(!ProgressRecords.validId(id))continue;boolean mine=name.equals(f.optString("name"));if(mine&&ownId.isEmpty())ownId=id;String raw=api.request("GET",API+"/"+id+"?alt=media","","");try{JSONObject entries=ProgressRecords.parse(raw);ProgressRecords.merge(merged,entries);if(mine)ProgressRecords.merge(remoteOwn,entries);}catch(Exception malformed){rejected++;}}page=listing.optString("nextPageToken");if(!page.isEmpty()&&!pages.add(page))throw new IOException("Google повторил страницу прогресса");}while(!page.isEmpty());ProgressRecords.merge(own,remoteOwn);ProgressRecords.merge(merged,own);
  if(own.length()>0&&!same(own,remoteOwn)){String body=ProgressRecords.document(device,own).toString();ProgressRecords.parse(body);if(ownId.isEmpty()){String boundary="meguboom_"+UUID.randomUUID();String metadata=new JSONObject().put("name",name).put("parents",new JSONArray().put("appDataFolder")).toString();String multipart="--"+boundary+"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n"+metadata+"\r\n--"+boundary+"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n"+body+"\r\n--"+boundary+"--\r\n";api.request("POST",UPLOAD+"?uploadType=multipart&fields=id",multipart,"multipart/related; boundary="+boundary);}else api.request("PATCH",UPLOAD+"/"+ownId+"?uploadType=media",body,"application/json; charset=UTF-8");}return new Result(own,merged,rejected);
 }
 static String http(String token,String method,String url,String body,String type)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+token);c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(!body.isEmpty()){c.setDoOutput(true);c.setRequestProperty("Content-Type",type);byte[] data=body.getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(data.length);try(OutputStream out=c.getOutputStream()){out.write(data);}}int code=c.getResponseCode();if(code==401||code==403)throw new AuthorizationException();if(code<200||code>=300)throw new IOException("Google Диск: "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>ProgressRecords.MAX_BYTES)throw new IOException("Слишком большой файл прогресса");out.write(buffer,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 static class AuthorizationException extends IOException{}
}
